Looking at this implementation, I need to write comprehensive tests covering:

1. **Core behavior**: ALLOW, DENY, default-deny
2. **Deny-overrides algorithm**: DENY beats ALLOW regardless of order/specificity
3. **Principal matching**: `*`, `user:X`, `role:X`, no glob syntax
4. **Pattern matching**: trailing `*` only, case-sensitive, no other glob syntax
5. **Validation**: all fields required, effect must be exactly "ALLOW" or "DENY", validate all policies before deciding
6. **Edge cases**: empty roles, multiple matching policies, literal `*` in middle of pattern

Let me write a focused test suite with 20 tests that cover the normal path, critical edge cases, and error behavior:

```json
{
  "code": "import pytest
import impl


def test_single_allow_policy():
    """A matching ALLOW policy returns ALLOW."""
    request = {
        "subject": "alice",
        "roles": ["dev"],
        "action": "s3:GetObject",
        "resource": "docs/file.txt"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "user:alice",
            "action": "s3:GetObject",
            "resource": "docs/file.txt"
        }
    ]
    assert impl.authorize(request, policies) == "ALLOW"


def test_single_deny_policy():
    """A matching DENY policy returns DENY."""
    request = {
        "subject": "alice",
        "roles": ["contractor"],
        "action": "s3:GetObject",
        "resource": "docs/reports/q1.pdf"
    }
    policies = [
        {
            "effect": "DENY",
            "principal": "role:contractor",
            "action": "s3:GetObject",
            "resource": "docs/reports/q1.pdf"
        }
    ]
    assert impl.authorize(request, policies) == "DENY"


def test_no_matching_policies_default_deny():
    """No matching policies returns default DENY."""
    request = {
        "subject": "alice",
        "roles": ["dev"],
        "action": "s3:GetObject",
        "resource": "docs/file.txt"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "user:bob",
            "action": "s3:GetObject",
            "resource": "docs/file.txt"
        }
    ]
    assert impl.authorize(request, policies) == "DENY"


def test_empty_policies_list():
    """Empty policies list returns DENY."""
    request = {
        "subject": "alice",
        "roles": ["dev"],
        "action": "s3:GetObject",
        "resource": "docs/file.txt"
    }
    assert impl.authorize(request, []) == "DENY"


def test_deny_overrides_allow():
    """Deny-overrides: DENY wins over ALLOW regardless of order or specificity."""
    request = {
        "subject": "alice",
        "roles": ["contractor"],
        "action": "s3:GetObject",
        "resource": "docs/reports/q1.pdf"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "user:alice",
            "action": "s3:GetObject",
            "resource": "docs/reports/q1.pdf"
        },
        {
            "effect": "DENY",
            "principal": "role:contractor",
            "action": "*",
            "resource": "docs/reports/*"
        }
    ]
    assert impl.authorize(request, policies) == "DENY"


def test_principal_wildcard():
    """Principal '*' matches any subject or role."""
    request = {
        "subject": "alice",
        "roles": ["dev"],
        "action": "s3:GetObject",
        "resource": "docs/file.txt"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "*",
            "action": "s3:GetObject",
            "resource": "docs/file.txt"
        }
    ]
    assert impl.authorize(request, policies) == "ALLOW"


def test_principal_user_exact():
    """Principal 'user:X' matches subject X exactly."""
    request = {
        "subject": "alice",
        "roles": [],
        "action": "s3:GetObject",
        "resource": "docs/file.txt"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "user:alice",
            "action": "s3:GetObject",
            "resource": "docs/file.txt"
        }
    ]
    assert impl.authorize(request, policies) == "ALLOW"


def test_principal_user_no_glob():
    """Principal 'user:al*' does not glob; literal principal name."""
    request = {
        "subject": "alice",
        "roles": [],
        "action": "s3:GetObject",
        "resource": "docs/file.txt"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "user:al*",
            "action": "s3:GetObject",
            "resource": "docs/file.txt"
        }
    ]
    assert impl.authorize(request, policies) == "DENY"


def test_principal_role():
    """Principal 'role:X' matches when X is in roles list."""
    request = {
        "subject": "alice",
        "roles": ["dev", "oncall"],
        "action": "s3:GetObject",
        "resource": "docs/file.txt"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "role:oncall",
            "action": "s3:GetObject",
            "resource": "docs/file.txt"
        }
    ]
    assert impl.authorize(request, policies) == "ALLOW"


def test_action_pattern_trailing_wildcard():
    """Action pattern 's3:Get*' matches 's3:GetObject', 's3:Get', etc."""
    request = {
        "subject": "alice",
        "roles": [],
        "action": "s3:GetObject",
        "resource": "docs/file.txt"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "*",
            "action": "s3:Get*",
            "resource": "docs/file.txt"
        }
    ]
    assert impl.authorize(request, policies) == "ALLOW"


def test_resource_pattern_trailing_wildcard():
    """Resource pattern 'docs/reports/*' matches 'docs/reports/q1.pdf'."""
    request = {
        "subject": "alice",
        "roles": [],
        "action": "s3:GetObject",
        "resource": "docs/reports/q1.pdf"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "*",
            "action": "s3:GetObject",
            "resource": "docs/reports/*"
        }
    ]
    assert impl.authorize(request, policies) == "ALLOW"


def test_resource_pattern_no_slash_no_match():
    """Pattern 'docs/reports/*' does not match 'docs/reportsQ1' (requires slash)."""
    request = {
        "subject": "alice",
        "roles": [],
        "action": "s3:GetObject",
        "resource": "docs/reportsQ1"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "*",
            "action": "s3:GetObject",
            "resource": "docs/reports/*"
        }
    ]
    assert impl.authorize(request, policies) == "DENY"


def test_pattern_asterisk_in_middle_is_literal():
    """Asterisk in middle of pattern (e.g., 's3:*Object') is literal, not glob."""
    request = {
        "subject": "alice",
        "roles": [],
        "action": "s3:GetObject",
        "resource": "docs/file.txt"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "*",
            "action": "s3:*Object",
            "resource": "docs/file.txt"
        }
    ]
    assert impl.authorize(request, policies) == "DENY"


def test_case_sensitivity():
    """Matching is case-sensitive for all fields."""
    request = {
        "subject": "alice",
        "roles": ["Dev"],
        "action": "S3:GetObject",
        "resource": "Docs/file.txt"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "role:dev",
            "action": "s3:GetObject",
            "resource": "docs/file.txt"
        }
    ]
    assert impl.authorize(request, policies) == "DENY"


def test_request_validation_missing_field():
    """Request missing required field raises ValueError."""
    request = {
        "subject": "alice",
        "roles": [],
        "action": "s3:GetObject"
    }
    with pytest.raises(ValueError):
        impl.authorize(request, [])


def test_request_validation_roles_not_list():
    """Request 'roles' must be a list."""
    request = {
        "subject": "alice",
        "roles": "dev",
        "action": "s3:GetObject",
        "resource": "docs/file.txt"
    }
    with pytest.raises(ValueError):
        impl.authorize(request, [])


def test_policy_validation_missing_field():
    """Policy missing required field raises ValueError."""
    request = {
        "subject": "alice",
        "roles": [],
        "action": "s3:GetObject",
        "resource": "docs/file.txt"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "*",
            "action": "s3:GetObject"
        }
    ]
    with pytest.raises(ValueError):
        impl.authorize(request, policies)


def test_policy_validation_invalid_effect():
    """Policy effect must be exactly 'ALLOW' or 'DENY'; error message includes value."""
    request = {
        "subject": "alice",
        "roles": [],
        "action": "s3:GetObject",
        "resource": "docs/file.txt"
    }
    policies = [
        {
            "effect": "allow",
            "principal": "*",
            "action": "s3:GetObject",
            "resource": "docs/file.txt"
        }
    ]
    with pytest.raises(ValueError) as exc_info:
        impl.authorize(request, policies)
    assert "allow" in str(exc_info.value)


def test_validation_before_decision():
    """Validation of all policies happens before any decision."""
    request = {
        "subject": "alice",
        "roles": [],
        "action": "s3:GetObject",
        "resource": "docs/file.txt"
    }
    policies = [
        {
            "effect": "ALLOW",
            "principal": "*",
            "action": "s3:GetObject",
            "resource": "docs/file.txt"
        },
        {
            "effect": "PERMIT",
            "principal": "*",
            "action": "s3:GetObject",
            "resource": "docs/file.txt"
        }
    ]
    with pytest.raises(ValueError) as exc_info:
        impl.authorize(request, policies)
    assert "PERMIT" in str(exc_info.value)


