            "principal": "role:contractor",
            "action": "*",
            "resource": "docs/reports/*"
        },
        {
            "effect": "ALLOW",
            "principal": "user:alice",
            "action": "s3:GetObject",
            "resource": "docs/reports/q1.pdf"
        }
    ]
    assert impl.authorize(request, policies) == "DENY"
